<?php
/**
 * Admin Dashboard & Site Management
 * Falhen Media Administration
 */

require_once __DIR__ . '/../config/db.php';
require_once __DIR__ . '/../includes/functions.php';
require_once __DIR__ . '/../includes/smtp_mailer.php';

// Enforce admin login
requireAdmin();

$pdo = getDBConnection();
$savedSuccess = false;
$savedMessage = '';

// Process settings save / section POST requests
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? (($_GET['ajax'] ?? '') === 'upload_cloudinary' ? 'upload_cloudinary_ajax' : 'save_settings');
    $currentRole = $_SESSION['admin_role'] ?? 'Staff';
    if ($currentRole === 'Talent Manager') {
        $currentRole = 'HR Manager';
        $_SESSION['admin_role'] = 'HR Manager';
    }

    if ($action === 'dismiss_clockin_reminder') {
        $_SESSION['dismissed_clockin_reminder'] = true;
        header('Content-Type: application/json');
        echo json_encode(['success' => true]);
        exit;
    }

    // RBAC Action to Section Mapping
    $actionSectionMap = [
        'save_hero'                  => 'hero',
        'save_stats'                 => 'stats',
        'save_bts'                   => 'bts',
        'upload_bts_photo'           => 'bts',
        'save_single_featured_item'  => 'portfolio',
        'save_service'               => 'services',
        'delete_service'             => 'services',
        'save_service_item'          => 'services',
        'delete_service_item'        => 'services',
        'toggle_service_visibility'  => 'services',
        'reorder_services'           => 'services',
        'save_testimonial'           => 'testimonials',
        'delete_testimonial'         => 'testimonials',
        'save_team_member'           => 'team',
        'delete_team_member'         => 'team',
        'save_blog_post'             => 'blog',
        'delete_blog_post'           => 'blog',
        'save_portfolio_item'        => 'portfolio',
        'delete_portfolio_item'      => 'portfolio',
        'save_career_item'           => 'careers',
        'delete_career_item'         => 'careers',
        'update_application_status'  => 'careers',
        'save_brands'                => 'brands',
        'save_brand_item'            => 'brands',
        'delete_brand_item'          => 'brands',
        'save_vendor'                => 'vendors',
        'delete_vendor'              => 'vendors',
        'save_onboarding_item'       => 'onboarding',
        'delete_onboarding_item'     => 'onboarding',
        'save_staff_account'         => 'staff_accounts',
        'delete_staff_account'       => 'staff_accounts',
        'toggle_staff_status'        => 'staff_accounts',
        'save_profile_details'       => 'my_profile',
        'change_profile_password'    => 'my_profile',
        'update_profile'             => 'my_profile',
        'change_password'            => 'my_profile',
        'clock_in'                   => 'attendance',
        'clock_out'                  => 'attendance',
        'start_break'                => 'attendance',
        'end_break'                  => 'attendance',
        'save_onboarding_bank'       => 'onboarding',
        'accept_offer'               => 'onboarding',
        'save_onboarding_ref1'       => 'onboarding',
        'acknowledge_sop'            => 'onboarding',
        'acknowledge_handbook'       => 'onboarding',
        'save_onboarding_id'         => 'onboarding',
        'admin_approve_onboarding_task' => 'onboarding',
        'admin_provide_agreement'    => 'onboarding',
        'admin_provide_offer'        => 'onboarding',
        'schedule_staff_meeting'     => 'directory',
        'post_announcement'          => 'announcements',
        'submit_leave_request'       => 'leaves',
        'update_leave_status'        => 'leaves',
        'send_comms_message'         => 'comms',
        'create_studio_task'         => 'comms',
        'update_studio_task'         => 'comms',
        'update_task_stage'          => 'comms',
        'toggle_task_checklist_item' => 'comms',
        'delete_studio_task'         => 'comms',
        'create_studio_task_stage'   => 'comms',
        'delete_studio_task_stage'   => 'comms',
        'update_studio_task_stage_label' => 'comms',
        'save_celebration_settings'         => 'celebrations',
        'save_employee_custom_wish'         => 'celebrations',
        'save_employee_celebration_profile' => 'celebrations',
        'post_instant_birthday_shoutout'    => 'celebrations',
        'post_instant_celebration_shoutout' => 'celebrations',
        'save_payment_gateways'             => 'payment_gateways',
        'process_employee_payment'          => 'payroll'
    ];

    $currentEmail = $_SESSION['admin_email'] ?? '';
    $currentUsername = $_SESSION['admin_username'] ?? '';

    $targetSection = $actionSectionMap[$action] ?? ($_GET['section'] ?? 'hero');
    if ($action !== 'upload_cloudinary_ajax' && !hasSectionAccess($targetSection, $currentRole, $currentEmail, $currentUsername)) {
        header('Location: /admin/index.php?section=' . urlencode($targetSection) . '&denied=1');
        exit;
    }

    if ($action === 'upload_cloudinary_ajax') {
        header('Content-Type: application/json');
        $folder = trim(strip_tags($_POST['folder'] ?? 'falhen/portfolio'));
        $fileToUpload = null;
        
        if (!empty($_FILES['file']['tmp_name'])) {
            $fileToUpload = $_FILES['file']['tmp_name'];
        } else if (!empty($_POST['cropped_data'])) {
            $fileToUpload = $_POST['cropped_data'];
        } else if (!empty($_POST['image_data'])) {
            $fileToUpload = $_POST['image_data'];
        } else if (!empty($_POST['image_url'])) {
            $fileToUpload = trim($_POST['image_url']);
        }

        if (empty($fileToUpload)) {
            echo json_encode(['success' => false, 'message' => 'No image file or cropped data received.']);
            exit;
        }

        $res = uploadToCloudinary($fileToUpload, $folder);
        if (!empty($res['success']) && !empty($res['url'])) {
            $uploadedUrl = $res['url'];

            // Auto-persist immediately if uploading a profile photo
            if ($folder === 'falhen/profile' || !empty($_POST['is_profile_avatar'])) {
                $_SESSION['admin_avatar'] = $uploadedUrl;

                $curUser = $_SESSION['admin_username'] ?? '';
                $curEmail = $_SESSION['admin_email'] ?? '';
                $curRole = $_SESSION['admin_role'] ?? 'Staff';

                if (isAdminUser($curRole, $curEmail, $curUser)) {
                    if (strtolower($curUser) === 'admin' || strtolower($curUser) === 'henry.falonipe' || strtolower($curEmail) === 'admin@falhen.com') {
                        saveAdminUserProfile(['avatar' => $uploadedUrl]);
                        saveStaffAccountByUsername('admin', ['avatar' => $uploadedUrl]);
                    } else {
                        saveStaffAccountByUsername($curUser, ['avatar' => $uploadedUrl]);
                    }
                }

                if (!empty($curUser)) {
                    saveStaffAccountByUsername($curUser, ['avatar' => $uploadedUrl]);
                }
                if (!empty($curEmail)) {
                    saveStaffAccountByUsername($curEmail, ['avatar' => $uploadedUrl]);
                }

                if ($pdo) {
                    try {
                        $stmt = $pdo->prepare("UPDATE `admin_users` SET `avatar` = ? WHERE `username` = ? OR `email` = ?");
                        $stmt->execute([$uploadedUrl, $curUser, $curEmail]);
                    } catch (Exception $e) {}
                }
            }

            echo json_encode(['success' => true, 'url' => $uploadedUrl]);
        } else {
            echo json_encode(['success' => false, 'message' => $res['message'] ?? 'Cloudinary upload failed.']);
        }
        exit;
    }

    if ($action === 'initiate_studio_call_ajax') {
        header('Content-Type: application/json');
        $targetUser = trim($_POST['target_user'] ?? '');
        $targetName = trim($_POST['target_name'] ?? 'Staff Member');
        $targetAvatar = trim($_POST['target_avatar'] ?? '');
        $callType = trim($_POST['call_type'] ?? 'audio');

        $callerName = !empty($_SESSION['admin_full_name']) ? $_SESSION['admin_full_name'] : (!empty($_SESSION['admin_name']) ? $_SESSION['admin_name'] : $currentUsername);
        $callerAvatar = $_SESSION['admin_avatar'] ?? '';

        if (empty($callerAvatar)) {
            $staffRepo = getStaffAccountsRepo();
            $userCanon = getCanonicalUsername($currentUsername);
            foreach ($staffRepo as $st) {
                if (getCanonicalUsername($st['username'] ?? '') === $userCanon) {
                    $callerAvatar = getCloudinaryUrl($st['avatar'] ?? '');
                    break;
                }
            }
        }
        if (empty($callerAvatar)) {
            $teamRepo = getTeamMembers();
            foreach ($teamRepo as $tm) {
                if (!empty($tm['name']) && str_contains(strtolower($tm['name']), strtolower($currentUsername))) {
                    $callerAvatar = getCloudinaryUrl($tm['image'] ?? '');
                    break;
                }
            }
        }

        $call = initiateStudioCallState($currentUsername, $callerName, $callerAvatar, $targetUser, $targetName, $targetAvatar, $callType);
        echo json_encode(['success' => true, 'call' => $call]);
        exit;
    }

    if ($action === 'update_studio_call_status_ajax') {
        header('Content-Type: application/json');
        $callId = trim($_POST['call_id'] ?? '');
        $status = trim($_POST['status'] ?? 'ended');

        $updated = updateStudioCallStatus($callId, $status);
        echo json_encode(['success' => true, 'call' => $updated]);
        exit;
    }

    if ($action === 'check_studio_call_signal_ajax') {
        header('Content-Type: application/json');
        $state = checkUserStudioCallState($currentUsername);
        echo json_encode(['success' => true, 'state' => $state]);
        exit;
    }

    if ($action === 'admin_approve_onboarding_task') {
        if (!isAdminUser($currentRole, $currentEmail, $currentUsername) && !isHRManager($currentRole)) {
            header('Location: /admin/index.php?section=onboarding&denied=1');
            exit;
        }

        $targetUser = trim($_POST['target_user'] ?? '');
        $taskKey = trim($_POST['task_key'] ?? '');
        $newStatus = trim($_POST['new_status'] ?? 'Approved');
        $reason = trim(strip_tags($_POST['rejection_reason'] ?? ''));

        $staffObj = getStaffAccountByUsername($targetUser);
        $canonicalTarget = !empty($staffObj['username']) ? $staffObj['username'] : $targetUser;

        $approver = $_SESSION['admin_full_name'] ?? $_SESSION['admin_username'] ?? 'HR & Admin Management';

        $extraData = [
            'approved_by' => $approver,
            'approved_at' => date('Y-m-d H:i:s')
        ];
        if ($newStatus === 'Rejected') {
            $extraData['rejection_reason'] = $reason;
            $extraData['rejected_by'] = $approver;
            $extraData['rejected_at'] = date('Y-m-d H:i:s');
        }

        updateUserOnboardingTaskStatus($canonicalTarget, $taskKey, $newStatus, $extraData);

        // If task is bank_details and approved, sync to staff repository profile
        if ($taskKey === 'bank_details' && $newStatus === 'Approved') {
            $onbData = getUserOnboardingData($canonicalTarget);
            $bd = $onbData['bank_details'] ?? [];
            if (!empty($bd['account_number'])) {
                saveStaffAccountByUsername($canonicalTarget, [
                    'bank_name'      => $bd['bank_name'] ?? 'Zenith Bank PLC',
                    'account_number' => $bd['account_number'] ?? '',
                    'account_name'   => $bd['account_name'] ?? ''
                ]);
            }
        }

        $taskLabel = str_replace(['_', '1', '2'], [' ', ' 1', ' 2'], ucfirst($taskKey));
        $_SESSION['saved_message'] = 'Onboarding task "' . $taskLabel . '" updated to ' . $newStatus . ' for ' . ($staffObj['full_name'] ?? ('@' . $canonicalTarget)) . '!';
        header('Location: /admin/index.php?section=onboarding&target_user=' . urlencode($canonicalTarget) . '&saved=1');
        exit;
    }

    if ($action === 'admin_approve_all_onboarding_tasks') {
        if (!isAdminUser($currentRole, $currentEmail, $currentUsername) && !isHRManager($currentRole)) {
            header('Location: /admin/index.php?section=onboarding&denied=1');
            exit;
        }

        $targetUser = trim($_POST['target_user'] ?? '');
        $staffObj = getStaffAccountByUsername($targetUser);
        $canonicalTarget = !empty($staffObj['username']) ? $staffObj['username'] : $targetUser;

        $approver = $_SESSION['admin_full_name'] ?? $_SESSION['admin_username'] ?? 'HR & Admin Management';
        $now = date('Y-m-d H:i:s');

        $allTasks = ['bank_details', 'offer_letter', 'employment_agreement', 'reference_1', 'reference_2', 'sop', 'staff_handbook', 'id_verification'];
        foreach ($allTasks as $tKey) {
            updateUserOnboardingTaskStatus($canonicalTarget, $tKey, 'Approved', [
                'approved_by' => $approver,
                'approved_at' => $now
            ]);
        }

        $_SESSION['saved_message'] = 'All 8 onboarding tasks verified and approved for ' . ($staffObj['full_name'] ?? ('@' . $canonicalTarget)) . ' by ' . $approver . '!';
        header('Location: /admin/index.php?section=onboarding&target_user=' . urlencode($canonicalTarget) . '&saved=1');
        exit;
    }

    if ($action === 'process_employee_payment') {
        if (!isAdminUser($currentRole, $currentEmail, $currentUsername) && strtolower($currentRole) !== 'hr manager') {
            header('Location: /admin/index.php?section=payroll&denied=1');
            exit;
        }

        $targetUsername = trim($_POST['target_user'] ?? $_POST['username'] ?? '');
        $staffObj = getStaffAccountByUsername($targetUsername);
        if (!$staffObj) {
            $staffObj = ['username' => $targetUsername, 'full_name' => $targetUsername, 'email' => $targetUsername . '@falhen.com', 'role' => 'Staff'];
        }

        $fullName = trim(strip_tags($_POST['full_name'] ?? ($staffObj['full_name'] ?? $targetUsername)));
        $email = trim(strip_tags($_POST['email'] ?? ($staffObj['email'] ?? '')));
        $role = trim(strip_tags($_POST['role'] ?? ($staffObj['role'] ?? 'Staff')));
        $payPeriod = trim(strip_tags($_POST['pay_period'] ?? date('F Y')));
        $periodMonth = sprintf('%02d', (int)($_POST['period_month'] ?? date('m')));
        $periodYear = trim(strip_tags($_POST['period_year'] ?? date('Y')));

        $rawBase = preg_replace('/^[₦$€£\s]+/u', '', trim($_POST['base_salary'] ?? '0'));
        $rawAllow = preg_replace('/^[₦$€£\s]+/u', '', trim($_POST['allowances'] ?? '0'));
        $rawDeduc = preg_replace('/^[₦$€£\s]+/u', '', trim($_POST['deductions'] ?? '0'));

        $baseSalary = (float)str_replace(',', '', $rawBase);
        $allowances = (float)str_replace(',', '', $rawAllow);
        $deductions = (float)str_replace(',', '', $rawDeduc);
        $netPay = ($baseSalary + $allowances) - $deductions;

        $currency = trim(strip_tags($_POST['currency'] ?? ($staffObj['currency'] ?? 'NGN')));
        $currSym = getCurrencySymbol($currency);
        $paymentMethod = trim(strip_tags($_POST['payment_method'] ?? 'Direct Bank Transfer'));
        $txRef = trim(strip_tags($_POST['tx_ref'] ?? ('FAL-PAY-' . date('Ym') . '-' . rand(100, 999))));
        $note = trim(strip_tags($_POST['note'] ?? ''));

        $processorName = $_SESSION['admin_full_name'] ?? $_SESSION['admin_username'] ?? 'HR Manager';

        $disbursement = processEmployeePayment([
            'username'       => $targetUsername,
            'full_name'      => $fullName,
            'email'          => $email,
            'role'           => $role,
            'pay_period'     => $payPeriod,
            'period_month'   => $periodMonth,
            'period_year'    => $periodYear,
            'base_salary'    => $baseSalary,
            'allowances'     => $allowances,
            'deductions'     => $deductions,
            'net_pay'        => $netPay,
            'currency'       => $currency,
            'status'         => 'Paid',
            'payment_method' => $paymentMethod,
            'tx_ref'         => $txRef,
            'note'           => $note,
            'processed_by'   => $processorName
        ]);

        if (!empty($email)) {
            sendSalaryPayoutNotificationEmail($email, $fullName, $payPeriod, $currSym . number_format($netPay, 2), $txRef);
        }

        $_SESSION['saved_message'] = 'Salary payout of ' . $currSym . number_format($netPay, 2) . ' for ' . htmlspecialchars($fullName) . ' (' . htmlspecialchars($payPeriod) . ') processed successfully!';
        header('Location: /admin/index.php?section=payroll&saved=1');
        exit;
    }

    if ($action === 'admin_reissue_sop') {
        if (!isAdminUser($currentRole, $currentEmail, $currentUsername)) {
            header('Location: /admin/index.php?section=onboarding&denied=1');
            exit;
        }

        $targetUser = trim($_POST['target_user'] ?? '');
        $sopTitle = trim(strip_tags($_POST['sop_title'] ?? 'Studio Standard Operating Procedures (19 Sections)'));
        $sopVersion = trim(strip_tags($_POST['sop_version'] ?? 'v2.0 - 2026 Official Studio Regulations'));
        $issuerName = trim(strip_tags($_POST['issuer_name'] ?? 'Oluwatosin Ligali'));
        $sopScope = trim(strip_tags($_POST['sop_scope'] ?? 'All Studio Departments & Staff'));
        $reissueNotes = trim(strip_tags($_POST['reissue_notes'] ?? ''));

        updateUserOnboardingTaskStatus($targetUser, 'sop', 'Issued', [
            'issued' => true,
            'acknowledged' => false,
            'signed' => false,
            'sop_title' => $sopTitle,
            'sop_version' => $sopVersion,
            'issuer_name' => $issuerName,
            'sop_scope' => $sopScope,
            'reissue_notes' => $reissueNotes,
            'reissued_at' => date('Y-m-d H:i:s'),
            'reissued_by' => $currentUsername
        ]);

        $_SESSION['saved_message'] = 'SOP terms saved and document re-issued for @' . $targetUser . '! Candidate re-acknowledgment requested.';
        header('Location: /admin/index.php?section=onboarding&target_user=' . urlencode($targetUser) . '&saved=1');
        exit;
    }

    if ($action === 'admin_reissue_handbook') {
        if (!isAdminUser($currentRole, $currentEmail, $currentUsername)) {
            header('Location: /admin/index.php?section=onboarding&denied=1');
            exit;
        }

        $targetUser = trim($_POST['target_user'] ?? '');
        $hbTitle = trim(strip_tags($_POST['handbook_title'] ?? 'Falhen Media Staff Handbook (30 Sections)'));
        $hbVersion = trim(strip_tags($_POST['handbook_version'] ?? '2026 Edition'));
        $reissueNotes = trim(strip_tags($_POST['reissue_notes'] ?? ''));

        updateUserOnboardingTaskStatus($targetUser, 'staff_handbook', 'Issued', [
            'issued' => true,
            'acknowledged' => false,
            'signed' => false,
            'handbook_title' => $hbTitle,
            'handbook_version' => $hbVersion,
            'reissue_notes' => $reissueNotes,
            'reissued_at' => date('Y-m-d H:i:s'),
            'reissued_by' => $currentUsername
        ]);

        $_SESSION['saved_message'] = 'Staff Handbook terms saved and document re-issued for @' . $targetUser . '! Candidate re-acknowledgment requested.';
        header('Location: /admin/index.php?section=onboarding&target_user=' . urlencode($targetUser) . '&saved=1');
        exit;
    }

    if ($action === 'admin_provide_agreement') {
        if (!isAdminUser($currentRole, $currentEmail, $currentUsername)) {
            header('Location: /admin/index.php?section=onboarding&denied=1');
            exit;
        }

        $targetUser = trim($_POST['target_user'] ?? '');
        $supName = trim(strip_tags($_POST['supervisor_name'] ?? 'Oluwatosin Ligali'));
        $supRole = trim(strip_tags($_POST['supervisor_role'] ?? 'Admin'));
        $workLoc = trim(strip_tags($_POST['work_location'] ?? 'Remote'));
        $workDays = trim(strip_tags($_POST['work_days'] ?? 'Monday to Friday'));
        $resTime = trim(strip_tags($_POST['resumption_time'] ?? '9:00 AM'));
        $closeTime = trim(strip_tags($_POST['closing_time'] ?? '5:00 PM'));
        $address = trim(strip_tags($_POST['address'] ?? '6 Olorunfunmi Street, Pedro, Gbagada, Lagos'));
        $phone = trim(strip_tags($_POST['phone'] ?? '08027487449'));

        updateUserOnboardingTaskStatus($targetUser, 'employment_agreement', 'Issued', [
            'issued' => true,
            'signed' => false,
            'supervisor_name' => $supName,
            'supervisor_role' => $supRole,
            'work_location' => $workLoc,
            'work_days' => $workDays,
            'resumption_time' => $resTime,
            'closing_time' => $closeTime,
            'address' => $address,
            'phone' => $phone,
            'document_url' => '/assets/docs/Employment_Agreement.pdf'
        ]);

        $_SESSION['saved_message'] = 'Employment Agreement terms saved and issued for @' . $targetUser . '!';
        header('Location: /admin/index.php?section=onboarding&target_user=' . urlencode($targetUser) . '&saved=1');
        exit;
    }

    if ($action === 'sign_employment_agreement') {
        $targetUser = trim($_POST['target_user'] ?? '');
        if (empty($targetUser)) {
            $targetUser = $_SESSION['admin_username'] ?? $adminProfile['username'] ?? $username;
        }
        $staffObj = getStaffAccountByUsername($targetUser);
        $canonicalTarget = !empty($staffObj['username']) ? $staffObj['username'] : $targetUser;

        $sigData = trim($_POST['signature_data'] ?? '');

        if (empty($sigData) || strlen($sigData) < 100) {
            $_SESSION['saved_message'] = 'Digital Signature Required: Please draw your signature on the signature pad before submitting the Employment Agreement.';
            header('Location: /admin/index.php?section=onboarding&target_user=' . urlencode($canonicalTarget));
            exit;
        }

        saveUserOnboardingSection($canonicalTarget, 'employment_agreement', [
            'status' => 'Submitted',
            'signed' => true,
            'signed_at' => date('Y-m-d H:i:s'),
            'signature_data' => $sigData
        ]);
        $_SESSION['saved_message'] = 'Employment Agreement digitally signed and submitted to HR & Admin for verification!';
        header('Location: /admin/index.php?section=onboarding&target_user=' . urlencode($canonicalTarget) . '&saved=1');
        exit;
    }

    if ($action === 'schedule_staff_meeting') {
        $targetUser = trim($_POST['target_user'] ?? '');
        $subject = trim(strip_tags($_POST['subject'] ?? 'Team Sync'));
        $meetingDate = trim(strip_tags($_POST['meeting_date'] ?? date('Y-m-d')));
        $meetingTime = trim(strip_tags($_POST['meeting_time'] ?? '10:00 AM'));
        $meetingDesc = trim(strip_tags($_POST['meeting_desc'] ?? ''));

        $meetings = $siteSettings['scheduled_meetings'] ?? [];
        $meetings[] = [
            'id'           => count($meetings) + 1,
            'organizer'    => $currentUsername,
            'target_user'  => $targetUser,
            'subject'      => $subject,
            'meeting_date' => $meetingDate,
            'meeting_time' => $meetingTime,
            'description'  => $meetingDesc,
            'created_at'   => date('Y-m-d H:i:s')
        ];
        saveSiteSettings(['scheduled_meetings' => $meetings]);

        $_SESSION['saved_message'] = 'Meeting invite "' . htmlspecialchars($subject) . '" successfully scheduled with @' . htmlspecialchars($targetUser) . ' for ' . htmlspecialchars($meetingDate) . ' at ' . htmlspecialchars($meetingTime) . '!';
        header('Location: /admin/index.php?section=directory&scheduled=1');
        exit;
    }

    if ($action === 'post_announcement') {
        $title = trim(strip_tags($_POST['title'] ?? ''));
        $category = trim(strip_tags($_POST['category'] ?? 'General'));
        $content = trim(strip_tags($_POST['content'] ?? ''));

        if (!empty($title) && !empty($content)) {
            $authorName = $_SESSION['admin_full_name'] ?? ($_SESSION['admin_name'] ?? $currentUsername);
            $authorDesignation = $_SESSION['admin_designation'] ?? ($currentRole ?? '');
            if (!empty($authorDesignation)) {
                $authorName .= ' (' . $authorDesignation . ')';
            }
            postSiteAnnouncement([
                'title' => $title,
                'category' => $category,
                'posted_by' => $authorName,
                'content' => $content
            ]);
            $_SESSION['saved_message'] = 'Announcement "' . htmlspecialchars($title) . '" published successfully!';
        }

        $redirectSection = trim($_POST['redirect_section'] ?? 'comms');
        $redirectTab = trim($_POST['redirect_tab'] ?? 'feeds');
        header('Location: /admin/index.php?section=' . urlencode($redirectSection) . '&tab=' . urlencode($redirectTab) . '&saved=1');
        exit;
    }

    if ($action === 'create_studio_task') {
        $title = trim(strip_tags($_POST['title'] ?? ''));
        $clientOrg = trim(strip_tags($_POST['client_org'] ?? ''));
        $stage = trim(strip_tags($_POST['stage'] ?? 'ideas'));
        $assigneeUser = trim(strip_tags($_POST['assignee_username'] ?? ''));
        $dueDate = trim(strip_tags($_POST['due_date'] ?? date('Y-m-d')));
        $priority = trim(strip_tags($_POST['priority'] ?? 'Medium'));
        $tags = trim(strip_tags($_POST['tags'] ?? ''));
        $description = trim(strip_tags($_POST['description'] ?? ''));
        // Parse dynamic checklist items & status
        $checklist = [];
        if (!empty($_POST['checklist_items']) && is_array($_POST['checklist_items'])) {
            $statuses = $_POST['checklist_status'] ?? [];
            foreach ($_POST['checklist_items'] as $idx => $txt) {
                $itemTxt = trim(strip_tags($txt));
                if (!empty($itemTxt)) {
                    $isDone = !empty($statuses[$idx]) && ($statuses[$idx] == '1' || $statuses[$idx] == 'on' || $statuses[$idx] == 'true');
