            'lemfi' => [
                'enabled'         => !empty($_POST['lemfi_enabled']),
                'tag'             => trim($_POST['lemfi_tag'] ?? '@falhen'),
                'account_name'    => trim($_POST['lemfi_account_name'] ?? 'Falhen Media Global'),
                'receiving_bank'  => trim($_POST['lemfi_receiving_bank'] ?? 'LemFi Virtual Account (Providus Bank / Wema)'),
                'account_number'  => trim($_POST['lemfi_account_number'] ?? ''),
                'country'         => trim($_POST['lemfi_country'] ?? 'Nigeria / Global Diaspora'),
                'instructions'    => trim($_POST['lemfi_instructions'] ?? '')
            ],
            'taptap' => [
                'enabled'          => !empty($_POST['taptap_enabled']),
                'recipient_name'   => trim($_POST['taptap_recipient_name'] ?? 'Falhen Media Limited'),
                'receiving_bank'   => trim($_POST['taptap_receiving_bank'] ?? 'Zenith Bank PLC / Access Bank'),
                'account_number'   => trim($_POST['taptap_account_number'] ?? ''),
                'domiciliary_usd'  => trim($_POST['taptap_domiciliary_usd'] ?? ''),
                'country'          => trim($_POST['taptap_country'] ?? 'Nigeria (Global Send: US, UK, EU, CA, UAE)'),
                'reference_prefix' => trim($_POST['taptap_reference_prefix'] ?? 'FAL-'),
                'instructions'     => trim($_POST['taptap_instructions'] ?? '')
            ],
            'paystack' => [
                'enabled'    => !empty($_POST['paystack_enabled']),
                'mode'       => trim($_POST['paystack_mode'] ?? 'test'),
                'public_key' => trim($_POST['paystack_public_key'] ?? ''),
                'secret_key' => trim($_POST['paystack_secret_key'] ?? '')
            ],
            'bank_transfer' => [
                'enabled'        => !empty($_POST['bank_transfer_enabled']),
                'bank_name'      => trim($_POST['bank_name'] ?? 'Zenith Bank PLC'),
                'account_name'   => trim($_POST['bank_account_name'] ?? 'Falhen Media Limited'),
                'account_number' => trim($_POST['bank_account_number'] ?? ''),
                'dom_usd_bank'   => trim($_POST['dom_usd_bank'] ?? 'Zenith Bank PLC (USD Domiciliary)'),
                'dom_usd_acc'    => trim($_POST['dom_usd_acc'] ?? ''),
                'dom_gbp_acc'    => trim($_POST['dom_gbp_acc'] ?? ''),
                'dom_eur_acc'    => trim($_POST['dom_eur_acc'] ?? ''),
                'swift_code'     => trim($_POST['swift_code'] ?? 'ZEIBNGLA')
            ]
        ];

        savePaymentGatewaysSettings($postedGateways);

        $_SESSION['saved_message'] = 'Global Payment Gateways (Raenest, LemFi, Taptap Send & Bank Details) updated successfully!';
        header('Location: /admin/index.php?section=payment_gateways&saved=1');
        exit;
    } else if ($action === 'process_employee_payment') {
        if (!isAdminUser($currentRole, $currentEmail, $currentUsername) && strtolower($currentRole) !== 'hr manager') {
            header('Location: /admin/index.php?section=payroll&denied=1');
            exit;
        }

        $targetUser   = trim($_POST['target_user'] ?? '');
        $fullName     = trim($_POST['full_name'] ?? $targetUser);
        $email        = trim($_POST['email'] ?? '');
        $role         = trim($_POST['role'] ?? 'Staff');
        $payPeriod    = trim($_POST['pay_period'] ?? date('F Y'));
        $periodMonth  = sprintf('%02d', (int)($_POST['period_month'] ?? date('m')));
        $periodYear   = (string)($_POST['period_year'] ?? date('Y'));

        $rawBase      = str_replace(',', '', trim($_POST['base_salary'] ?? '0'));
        $rawAllow     = str_replace(',', '', trim($_POST['allowances'] ?? '0'));
        $rawDeduc     = str_replace(',', '', trim($_POST['deductions'] ?? '0'));

        $baseSal      = (float)$rawBase;
        $allowances   = (float)$rawAllow;
        $deductions   = (float)$rawDeduc;
        $netPay       = ($baseSal + $allowances) - $deductions;

        $currency     = trim($_POST['currency'] ?? ($staffObj['currency'] ?? 'NGN'));
        $currSym      = getCurrencySymbol($currency);
        $paymentMethod = trim($_POST['payment_method'] ?? 'Direct Bank Transfer');
        $txRef        = trim($_POST['tx_ref'] ?? ('FAL-PAY-' . $periodYear . $periodMonth . '-' . rand(100, 999)));
        $processedBy  = $_SESSION['admin_full_name'] ?? $_SESSION['admin_name'] ?? 'HR & Finance';

        $disb = processEmployeePayment([
            'username'       => $targetUser,
            'full_name'      => $fullName,
            'email'          => $email,
            'role'           => $role,
            'pay_period'     => $payPeriod,
            'period_month'   => $periodMonth,
            'period_year'    => $periodYear,
            'base_salary'    => $baseSal,
            'allowances'     => $allowances,
            'deductions'     => $deductions,
            'net_pay'        => $netPay,
            'currency'       => $currency,
            'status'         => 'Paid',
            'payment_method' => $paymentMethod,
            'tx_ref'         => $txRef,
            'processed_by'   => $processedBy
        ]);

        $_SESSION['saved_message'] = 'Salary payment of ' . $currSym . number_format($netPay, 2) . ' via ' . htmlspecialchars($paymentMethod) . ' processed for ' . htmlspecialchars($fullName) . ' (' . htmlspecialchars($payPeriod) . ')!';
        header('Location: /admin/index.php?section=payroll&month=' . urlencode($periodMonth) . '&year=' . urlencode($periodYear) . '&saved=1');
        exit;
    } else if ($action === 'bulk_process_payroll') {
        if (!isAdminUser($currentRole, $currentEmail, $currentUsername) && strtolower($currentRole) !== 'hr manager') {
            header('Location: /admin/index.php?section=payroll&denied=1');
            exit;
        }

        $periodMonth   = sprintf('%02d', (int)($_POST['period_month'] ?? date('m')));
        $periodYear    = (string)($_POST['period_year'] ?? date('Y'));
        $payPeriod     = date('F Y', mktime(0, 0, 0, (int)$periodMonth, 1, (int)$periodYear));
        $paymentMethod = trim($_POST['bulk_payment_method'] ?? 'Direct Bank Transfer');
        $processedBy   = $_SESSION['admin_full_name'] ?? $_SESSION['admin_name'] ?? 'HR & Finance';

        $allStaff = array_values(getStaffAccountsRepo());
        $countPaid = 0;
        $totalPaidSum = 0;

        foreach ($allStaff as $idx => $st) {
            $stCurr     = $st['currency'] ?? 'NGN';
            $defaultDeduc = in_array($stCurr, ['USD', 'EUR', 'GBP', 'CAD', 'AUD'], true) ? 0 : 10000;
            $defaultAllow = in_array($stCurr, ['USD', 'EUR', 'GBP', 'CAD', 'AUD'], true) ? 0 : 20000;
            $baseSal    = (float)($st['base_salary'] ?? 250000);
            $allowances = (float)($st['allowances'] ?? $defaultAllow);
            $deductions = (float)($st['deductions'] ?? $defaultDeduc);
            $netPay     = ($baseSal + $allowances) - $deductions;
            if ($netPay < 0) $netPay = 0;
            $txRef      = 'FAL-PAY-' . $periodYear . $periodMonth . '-' . sprintf('%03d', $idx + 1);

            processEmployeePayment([
                'username'       => $st['username'] ?? '',
                'full_name'      => $st['full_name'] ?? '',
                'email'          => $st['email'] ?? '',
                'role'           => $st['role'] ?? 'Staff',
                'pay_period'     => $payPeriod,
                'period_month'   => $periodMonth,
                'period_year'    => $periodYear,
                'base_salary'    => $baseSal,
                'allowances'     => $allowances,
                'deductions'     => $deductions,
                'net_pay'        => $netPay,
                'currency'       => $stCurr,
                'status'         => 'Paid',
                'payment_method' => $paymentMethod,
                'tx_ref'         => $txRef,
                'processed_by'   => $processedBy
            ]);
            $countPaid++;
            $totalPaidSum += $netPay;
        }

        $_SESSION['saved_message'] = "Bulk monthly payroll processed successfully for {$countPaid} active team members for {$payPeriod}!";
        header('Location: /admin/index.php?section=payroll&month=' . urlencode($periodMonth) . '&year=' . urlencode($periodYear) . '&saved=1');
        exit;
    } else if ($action === 'delete_vendor') {
        $vendorId = trim($_POST['vendor_id'] ?? '');
        if (!empty($vendorId)) {
            deleteVendorRecord($vendorId);
            $_SESSION['saved_message'] = 'Vendor record deleted successfully.';
        }
        header('Location: /admin/index.php?section=vendors&tab=' . urlencode($_POST['redirect_tab'] ?? 'directory') . '&saved=1');
        exit;
    } else if ($action === 'update_vendor_status') {
        $vendorId = trim($_POST['vendor_id'] ?? '');
        $newStatus = trim($_POST['status'] ?? 'active');
        if (!empty($vendorId)) {
            updateVendorStatus($vendorId, $newStatus);
            $_SESSION['saved_message'] = 'Vendor status updated to ' . ucfirst(str_replace('_', ' ', $newStatus)) . '.';
        }
        header('Location: /admin/index.php?section=vendors&tab=' . urlencode($_POST['redirect_tab'] ?? 'directory') . '&saved=1');
        exit;
    } else if ($action === 'save_vendor') {
        $vendorData = $_POST;
        if (empty($vendorData['reference_code']) && empty($vendorData['id'])) {
            $vendorData['reference_code'] = generateVendorReference();
        }
        if (empty($vendorData['signature_date'])) {
            $vendorData['signature_date'] = date('Y-m-d');
        }
        if (empty($vendorData['signature_name'])) {
            $vendorData['signature_name'] = trim($vendorData['full_name'] ?? 'Admin Added');
        }
        $vendorData['msa_agreed'] = 1;
        $vendorData['nda_agreed'] = 1;
        $vendorData['workplace_policy_agreed'] = 1;

        // Auto combine street, city, state, zip into address if not explicitly passed
        if (empty($vendorData['address']) && (!empty($vendorData['street_address']) || !empty($vendorData['city']))) {
            $parts = array_filter([$vendorData['street_address'] ?? '', $vendorData['city'] ?? '', trim(($vendorData['state'] ?? '') . ' ' . ($vendorData['zip'] ?? ''))]);
            $vendorData['address'] = implode(', ', $parts);
        }

        saveVendorRecord($vendorData);
        $_SESSION['saved_message'] = 'Vendor details for "' . htmlspecialchars($vendorData['full_name'] ?? 'Vendor') . '" saved successfully.';
        header('Location: /admin/index.php?section=vendors&tab=' . urlencode($_POST['redirect_tab'] ?? 'directory') . '&saved=1');
        exit;
    } else if ($action === 'save_vendor_gig') {
        $gigId = trim($_POST['id'] ?? '');
        if (empty($gigId)) {
            $gigId = 'GIG-' . date('Y') . '-' . str_pad((string)mt_rand(100, 999), 3, '0', STR_PAD_LEFT);
        }

        $assignedRef = trim($_POST['assigned_to_ref'] ?? '');
        $vendor = !empty($assignedRef) ? getVendorById($assignedRef) : null;

        $gigData = [
            'id'                  => $gigId,
            'title'               => trim($_POST['title'] ?? 'Production Shoot'),
            'client'              => trim($_POST['client'] ?? 'Falhen Media Production'),
            'shoot_date'          => trim($_POST['shoot_date'] ?? date('Y-m-d')),
            'end_date'            => trim($_POST['end_date'] ?? $_POST['shoot_date'] ?? date('Y-m-d')),
            'call_time'           => trim($_POST['call_time'] ?? '08:00 AM'),
            'wrap_time'           => trim($_POST['wrap_time'] ?? '06:00 PM'),
            'location'            => trim($_POST['location'] ?? 'Falhen Soundstage, Lagos'),
            'role'                => trim($_POST['role'] ?? 'Lead Videographer'),
            'day_rate'            => trim($_POST['day_rate'] ?? ''),
            'status'              => trim($_POST['status'] ?? 'assigned'),
            'assigned_to_ref'     => $vendor['reference_code'] ?? $assignedRef,
            'assigned_to_email'   => $vendor['email'] ?? '',
            'assigned_to_name'    => $vendor['full_name'] ?? '',
            'director'            => trim($_POST['director'] ?? 'Oluwatosin Ligali (Executive Producer)'),
            'director_phone'      => trim($_POST['director_phone'] ?? '08027487449'),
            'deliverables_status' => trim($_POST['deliverables_status'] ?? 'Pending Shoot Execution'),
            'payment_status'      => trim($_POST['payment_status'] ?? ''),
            'notes'               => trim($_POST['notes'] ?? '')
        ];

        // Preserve existing call sheet URLs & schedule CSV if not replaced
        $existingGig = getVendorGigById($gigId);
        if ($existingGig) {
            $gigData['call_sheet_name'] = $existingGig['call_sheet_name'] ?? ('CallSheet_' . $gigId . '.pdf');
            $gigData['call_sheet_url'] = $existingGig['call_sheet_url'] ?? ('/download_call_sheet.php?gig_id=' . urlencode($gigId));
            $gigData['uploaded_call_sheet'] = $existingGig['uploaded_call_sheet'] ?? '';
            $gigData['uploaded_call_sheet_name'] = $existingGig['uploaded_call_sheet_name'] ?? '';
            $gigData['uploaded_call_sheet_at'] = $existingGig['uploaded_call_sheet_at'] ?? '';
            $gigData['schedule_csv_url'] = $existingGig['schedule_csv_url'] ?? '';
            $gigData['schedule_csv_name'] = $existingGig['schedule_csv_name'] ?? '';
            $gigData['schedule_items'] = $existingGig['schedule_items'] ?? [];
        } else {
            $gigData['call_sheet_name'] = 'CallSheet_' . $gigId . '.pdf';
            $gigData['call_sheet_url'] = '/download_call_sheet.php?gig_id=' . urlencode($gigId);
            $gigData['uploaded_call_sheet'] = '';
            $gigData['uploaded_call_sheet_name'] = '';
            $gigData['schedule_csv_url'] = '';
            $gigData['schedule_csv_name'] = '';
            $gigData['schedule_items'] = [];
        }

        // Handle Call Sheet File Upload if provided
        if (!empty($_FILES['call_sheet_file']['name']) && $_FILES['call_sheet_file']['error'] === UPLOAD_ERR_OK) {
            $f = $_FILES['call_sheet_file'];
            $ext = strtolower(pathinfo($f['name'], PATHINFO_EXTENSION));
            $allowed = ['pdf', 'docx', 'doc', 'jpg', 'png'];
            if (in_array($ext, $allowed, true)) {
                $targetDir = __DIR__ . '/../uploads/callsheets/';
                if (!is_dir($targetDir)) {
                    @mkdir($targetDir, 0777, true);
                }
                $safeName = 'CallSheet_' . preg_replace('/[^a-zA-Z0-9_\.-]/', '_', $gigId) . '_' . time() . '.' . $ext;
                if (move_uploaded_file($f['tmp_name'], $targetDir . $safeName)) {
                    $gigData['call_sheet_url'] = '/uploads/callsheets/' . $safeName;
                    $gigData['call_sheet_name'] = $f['name'];
                }
            }
        }

        // Handle Production Schedule CSV Upload if provided
        if (!empty($_FILES['schedule_csv_file']['name']) && $_FILES['schedule_csv_file']['error'] === UPLOAD_ERR_OK) {
            $fCsv = $_FILES['schedule_csv_file'];
            $csvExt = strtolower(pathinfo($fCsv['name'], PATHINFO_EXTENSION));
            if ($csvExt === 'csv' || str_contains($fCsv['type'] ?? '', 'csv') || str_contains($fCsv['type'] ?? '', 'text/plain')) {
                $targetCsvDir = __DIR__ . '/../uploads/schedules/';
                if (!is_dir($targetCsvDir)) {
                    @mkdir($targetCsvDir, 0777, true);
                }
                $safeCsvName = 'Schedule_' . preg_replace('/[^a-zA-Z0-9_\.-]/', '_', $gigId) . '_' . time() . '.csv';
                if (move_uploaded_file($fCsv['tmp_name'], $targetCsvDir . $safeCsvName)) {
                    $gigData['schedule_csv_url'] = '/uploads/schedules/' . $safeCsvName;
                    $gigData['schedule_csv_name'] = $fCsv['name'];

                    // Parse CSV rows into structured schedule items
                    $parsedItems = [];
                    if (($handle = fopen($targetCsvDir . $safeCsvName, 'r')) !== false) {
                        $rowIndex = 0;
                        while (($data = fgetcsv($handle, 2000, ',')) !== false) {
                            $rowIndex++;
                            if ($rowIndex === 1) {
                                $firstCol = strtolower(trim($data[0] ?? ''));
                                if ($firstCol === 'time' || str_contains($firstCol, 'time')) {
                                    continue;
                                }
                            }
                            if (empty(array_filter($data))) continue;
                            $parsedItems[] = [
                                'time'        => trim($data[0] ?? ''),
                                'scene'       => trim($data[1] ?? ''),
                                'description' => trim($data[2] ?? ''),
                                'personnel'   => trim($data[3] ?? '')
                            ];
                        }
                        fclose($handle);
                    }
                    if (!empty($parsedItems)) {
                        $gigData['schedule_items'] = $parsedItems;
                    }
                }
            }
        }

        saveVendorGig($gigData);
        $_SESSION['saved_message'] = 'Production Gig "' . htmlspecialchars($gigData['title']) . '" saved successfully!';
        header('Location: /admin/index.php?section=vendors&tab=gigs&saved=1');
        exit;
    } else if ($action === 'assign_gig_to_vendor') {
        $gigId = trim($_POST['gig_id'] ?? '');
        $vendorRef = trim($_POST['vendor_ref'] ?? '');
        $gig = getVendorGigById($gigId);
        if ($gig) {
            $vendor = !empty($vendorRef) ? getVendorById($vendorRef) : null;
            $gig['assigned_to_ref'] = $vendor ? $vendor['reference_code'] : '';
            $gig['assigned_to_email'] = $vendor ? $vendor['email'] : '';
            $gig['assigned_to_name'] = $vendor ? $vendor['full_name'] : '';
            if ($vendor && ($gig['status'] ?? '') === '') {
                $gig['status'] = 'assigned';
            }
            saveVendorGig($gig);
            $_SESSION['saved_message'] = 'Gig assigned to ' . ($vendor ? htmlspecialchars($vendor['full_name']) : 'unassigned') . ' successfully.';
        }
        $redirectTab = $_POST['redirect_tab'] ?? 'gigs';
        header('Location: /admin/index.php?section=vendors&tab=' . urlencode($redirectTab) . '&saved=1');
        exit;
    } else if ($action === 'update_gig_status') {
        $gigId = trim($_POST['gig_id'] ?? '');
        $newStatus = trim($_POST['status'] ?? 'assigned');
        $delivStatus = trim($_POST['deliverables_status'] ?? '');
        $payStatus = trim($_POST['payment_status'] ?? '');

        $gig = getVendorGigById($gigId);
        if ($gig) {
            $gig['status'] = $newStatus;
            if (!empty($delivStatus)) {
                $gig['deliverables_status'] = $delivStatus;
            }
            if (!empty($payStatus)) {
                $gig['payment_status'] = $payStatus;
            }
            if ($newStatus === 'done' && empty($gig['completed_at'])) {
                $gig['completed_at'] = date('Y-m-d H:i:s');
            }
            saveVendorGig($gig);
            $_SESSION['saved_message'] = 'Gig #' . htmlspecialchars($gigId) . ' status updated to ' . ucfirst($newStatus) . '.';
        }
        header('Location: /admin/index.php?section=vendors&tab=' . urlencode($_POST['redirect_tab'] ?? 'gigs') . '&saved=1');
        exit;
    } else if ($action === 'delete_vendor_gig') {
        $gigId = trim($_POST['gig_id'] ?? '');
        if (!empty($gigId)) {
            deleteVendorGig($gigId);
            $_SESSION['saved_message'] = 'Production Gig #' . htmlspecialchars($gigId) . ' deleted successfully.';
        }
        header('Location: /admin/index.php?section=vendors&tab=gigs&saved=1');
        exit;
    }
}

// Fetch current site settings
$settings = getSiteSettings();

// Fetch inquiries & statistics
$inquiries = [];
$stats = [
    'total_inquiries' => 0,
    'new_inquiries'   => 0,
    'total_services'  => 7,
    'total_portfolio' => 5
];

if ($pdo) {
    try {
        $inquiries = $pdo->query("SELECT * FROM `inquiries` ORDER BY `id` DESC")->fetchAll();
        $stats['total_inquiries'] = count($inquiries);
        $stats['new_inquiries']   = count(array_filter($inquiries, fn($i) => ($i['status'] ?? '') === 'new'));
    } catch (Exception $e) {}
}

$adminProfile = getAdminUserProfile();
$username = $_SESSION['admin_username'] ?? $adminProfile['username'] ?? 'admin';
$userEmail = $_SESSION['admin_email'] ?? $adminProfile['email'] ?? 'admin@falhen.com';
$userRole = $_SESSION['admin_role'] ?? $adminProfile['role'] ?? 'Administrator';
if ($userRole === 'Talent Manager') {
    $userRole = 'HR Manager';
    $_SESSION['admin_role'] = 'HR Manager';
}

$isSuperAdmin = (strtolower($username) === 'admin' || strtolower($username) === 'oluwatosin.ligali' || strtolower($userEmail) === 'mail@falhenmedia.com' || strtolower($userEmail) === 'admin@falhen.com');

    $currentStaffAcc = getStaffAccountByUsername($username);
    if (!$currentStaffAcc && !empty($userEmail)) {
        $currentStaffAcc = getStaffAccountByUsername($userEmail);
    }

    if ($currentStaffAcc) {
        $userFullName    = !empty($currentStaffAcc['full_name']) ? $currentStaffAcc['full_name'] : ($_SESSION['admin_full_name'] ?? $username);
        $userAvatar      = !empty($currentStaffAcc['avatar']) ? $currentStaffAcc['avatar'] : ($_SESSION['admin_avatar'] ?? '');
        $userRole        = !empty($currentStaffAcc['role']) ? $currentStaffAcc['role'] : ($_SESSION['admin_role'] ?? 'Staff');
        $userDesignation = !empty($currentStaffAcc['designation']) ? $currentStaffAcc['designation'] : ($_SESSION['admin_designation'] ?? ($currentStaffAcc['role'] ?? 'Creative Specialist'));
        
        $_SESSION['admin_full_name']   = $userFullName;
        $_SESSION['admin_avatar']      = $userAvatar;
        $_SESSION['admin_role']        = $userRole;
        $_SESSION['admin_designation'] = $userDesignation;
    } elseif ($isSuperAdmin) {
        $userAvatar      = !empty($adminProfile['avatar']) ? $adminProfile['avatar'] : ($_SESSION['admin_avatar'] ?? '');
        $userFullName    = !empty($adminProfile['full_name']) ? $adminProfile['full_name'] : ($_SESSION['admin_full_name'] ?? 'Henry Falonipe');
        $userRole        = !empty($adminProfile['role']) ? $adminProfile['role'] : ($_SESSION['admin_role'] ?? 'Super Admin');
        $userDesignation = !empty($adminProfile['designation']) ? $adminProfile['designation'] : ($_SESSION['admin_designation'] ?? 'Creative Director & Founder');

        $_SESSION['admin_avatar']      = $userAvatar;
        $_SESSION['admin_full_name']   = $userFullName;
        $_SESSION['admin_role']        = $userRole;
        $_SESSION['admin_designation'] = $userDesignation;
    } else {
        $userAvatar      = $_SESSION['admin_avatar'] ?? '';
        $userFullName    = $_SESSION['admin_full_name'] ?? ucwords(str_replace('.', ' ', $username));
        $userDesignation = $_SESSION['admin_designation'] ?? 'Creative Specialist';
    }
$userInitial = strtoupper(substr($userFullName ?: 'S', 0, 1));

// Resolve active section & evaluate RBAC permission
$rawSection = $_GET['section'] ?? null;
if ($rawSection === null) {
    $activeSection = getUserFirstAllowedSection($userRole, $userEmail, $username);
} else {
    $activeSection = $rawSection;
}

// Check Initial Password Setup Gatekeeper for Activated Accounts
$mustChangePassword = !empty($_SESSION['must_change_password']) || isset($_GET['force_password_change']);
if ($mustChangePassword) {
    if (!in_array($activeSection, ['my_profile', 'profile', 'logout'], true)) {
        header('Location: /admin/index.php?section=my_profile&force_password_change=1');
        exit;
    }
}

// Check Onboarding Completion Gatekeeper for Staff Members
$userOnboardingProgress = getOnboardingProgress($username);
$isHRorAdminUser = isAdminUser($userRole, $userEmail, $username);
$isOnboardingIncomplete = (!$isHRorAdminUser && ($userOnboardingProgress['percent'] ?? 0) < 100);

if ($isOnboardingIncomplete) {
    // Force onboarding section unless accessing onboarding, my_profile, profile or logout
    if (!in_array($activeSection, ['onboarding', 'my_profile', 'profile', 'logout'], true)) {
        header('Location: /admin/index.php?section=onboarding&onboarding_required=1');
        exit;
    }
}

$isAccessDenied = !hasSectionAccess($activeSection, $userRole, $userEmail, $username) || isset($_GET['denied']);

?>
