                $totalStaffCount = count($allStaffList);
                
                $realAnnouncements = getSiteAnnouncements('all');
                $dashAnnouncements = array_slice($realAnnouncements, 0, 3);

                // Compute real staff birthdays & celebrations
                $celebrationsList = [];
                $currentMonth = (int)date('m');
                $currentDay = (int)date('d');

                $allStaffAccounts = array_values(getStaffAccountsRepo());
                $adminProfileItem = getAdminUserProfile();

                $allPeopleList = $allStaffAccounts;
                if (!empty($adminProfileItem) && is_array($adminProfileItem)) {
                    $adminInRepo = false;
                    foreach ($allPeopleList as &$sa) {
                        $saUser = strtolower($sa['username'] ?? '');
                        $saEmail = strtolower($sa['email'] ?? '');
                        $admUser = strtolower($adminProfileItem['username'] ?? 'admin');
                        $admEmail = strtolower($adminProfileItem['email'] ?? '');

                        if (($saUser === 'admin' && $admUser === 'admin') || ($saUser === $admUser && !empty($admUser)) || (!empty($admEmail) && $saEmail === $admEmail)) {
                            $adminInRepo = true;
                            if (!empty($adminProfileItem['dob'])) {
                                $sa['dob'] = $adminProfileItem['dob'];
                            }
                            if (!empty($adminProfileItem['full_name'])) {
                                $sa['full_name'] = $adminProfileItem['full_name'];
                            }
                            if (!empty($adminProfileItem['avatar'])) {
                                $sa['avatar'] = $adminProfileItem['avatar'];
                            }
                        }
                    }
                    unset($sa);

                    if (!$adminInRepo) {
                        $allPeopleList[] = $adminProfileItem;
                    }
                }

                // Also include team members if available
                if (function_exists('getTeamMembers')) {
                    $siteTeamMembers = array_values(getTeamMembers());
                    foreach ($siteTeamMembers as $tm) {
                        if (!empty($tm['dob'])) {
                            $allPeopleList[] = [
                                'full_name' => $tm['name'] ?? '',
                                'role'      => $tm['role'] ?? ($tm['title'] ?? 'Team Member'),
                                'avatar'    => $tm['image'] ?? '',
                                'dob'       => $tm['dob']
                            ];
                        }
                    }
                }

                foreach ($allPeopleList as $stMember) {
                    $stName = $stMember['full_name'] ?? ($stMember['username'] ?? '');
                    if (empty($stName)) continue;
                    $stRole = $stMember['designation'] ?? ($stMember['role'] ?? 'Staff Member');
                    $stAvatar = $stMember['avatar'] ?? '';
                    $dobVal = $stMember['dob'] ?? '';

                    if (!empty($dobVal)) {
                        $dobTime = strtotime($dobVal);
                        if ($dobTime) {
                            $m = (int)date('m', $dobTime);
                            $d = (int)date('d', $dobTime);
                            $dateFormatted = date('M d', $dobTime);
                            $isToday = ($m === $currentMonth && $d === $currentDay);

                            $celebrationsList[] = [
                                'name'        => $stName,
                                'role'        => $stRole,
                                'designation' => $stRole,
                                'avatar'      => $stAvatar,
                                'date_str'    => $dateFormatted,
                                'is_today'    => $isToday,
                                'month'       => $m,
                                'day'         => $d
                            ];
                        }
                    }
                }

                // Deduplicate celebrationsList so each employee is displayed only once
                $dedupCelebrations = [];
                $seenCelebs = [];
                foreach ($celebrationsList as $cItem) {
                    $key = strtolower(trim($cItem['name']));
                    if (!empty($key) && !isset($seenCelebs[$key])) {
                        $seenCelebs[$key] = true;
                        $dedupCelebrations[] = $cItem;
                    }
                }
                $celebrationsList = $dedupCelebrations;

                // Sort birthdays so Today's birthdays and upcoming birthdays appear at top
                if (!empty($celebrationsList)) {
                    usort($celebrationsList, function($a, $b) {
                        if (!empty($a['is_today']) && empty($b['is_today'])) return -1;
                        if (empty($a['is_today']) && !empty($b['is_today'])) return 1;
                        
                        $mA = (int)($a['month'] ?? 0);
                        $mB = (int)($b['month'] ?? 0);
                        $dA = (int)($a['day'] ?? 0);
                        $dB = (int)($b['day'] ?? 0);

                        if ($mA === $mB) {
                            return $dA <=> $dB;
                        }
                        return $mA <=> $mB;
                    });
                }

                // Fetch Real Leave Applications
                $allLeaves = $siteSettings['leave_applications'] ?? [];
                $userLeaves = array_filter($allLeaves, function($l) use ($username) {
