    <!-- GLOBAL SIDEBAR & MOBILE RESPONSIVE SCRIPT -->
    <script>
    function toggleAvatarDropdown(e) {
        if (e) e.stopPropagation();
        var menu = document.getElementById('topbarAvatarDropdown');
        if (menu) {
            var isVisible = menu.style.display === 'block';
            menu.style.display = isVisible ? 'none' : 'block';
        }
    }

    document.addEventListener('click', function(e) {
        var menu = document.getElementById('topbarAvatarDropdown');
        var btn = document.getElementById('topbarAvatarBtn');
        if (menu && menu.style.display === 'block') {
            if (btn && !btn.contains(e.target) && !menu.contains(e.target)) {
                menu.style.display = 'none';
            }
        }
    });

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            var menu = document.getElementById('topbarAvatarDropdown');
            if (menu) menu.style.display = 'none';
        }
    });

    function toggleMobileSidebar() {
        var sidebar = document.querySelector('.sidebar');
        var backdrop = document.getElementById('sidebarBackdrop');
        if (sidebar) {
            sidebar.classList.toggle('mobile-open');
        }
        if (backdrop) {
            backdrop.classList.toggle('active');
        }
    }

    function toggleNavCategory(header) {
        if (!header) return;
        header.classList.toggle('collapsed');
        var list = header.nextElementSibling;
        if (list && list.classList.contains('nav-list')) {
            if (header.classList.contains('collapsed')) {
                list.style.display = 'none';
            } else {
                list.style.display = 'block';
            }
        }
    }
    </script>

